SELECT member_id || '-' || strftime(stat_month, '%Y-%m') AS member_month, member_id, stat_month, COUNT(*) AS valid_order_cnt, SUM(paid_cents - refund_cents) AS net_sales_cents FROM (SELECT member_id, date_trunc('month', ordered_at) AS stat_month, paid_cents, refund_cents FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0) v GROUP BY member_id, stat_month